#include <iostream>
#include <string>
#include <cctype>
using namespace std;

using ll = long long;
using pii = pair<int, int>;
using pll = pair<ll, ll>;

ll mod_pow(ll base, ll exp, ll mod) {
    ll result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

constexpr int MAX_N = 30005;
constexpr ll MOD_VAL = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    string res;
    bool replaced_at = false;
    const size_t n = s.length();

    for (size_t i = 0; i < n; ++i) {
        if (i > 0 && i + 2 < n) {
            if (s[i] == 'd' && s[i+1] == 'o' && s[i+2] == 't') {
                res += '.';
                i += 2;
                continue;
            }
        }

        if (!replaced_at && i > 0 && i + 1 < n) {
            if (s[i] == 'a' && s[i+1] == 't') {
                res += '@';
                i += 1;
                replaced_at = true;
                continue;
            }
        }

        res += s[i];
    }

    cout << res << '\n';
    return 0;
}
